import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { DispositivoService } from '../../../services/dispositivo.service';
import { Subscription } from 'rxjs';
import { CommonModule } from '@angular/common';
import { Dispositivos } from '../../../enums/dispositivos.enum';
import { Router } from '@angular/router';

@Component({
  selector: 'barra-botoes',
  templateUrl: './barra-botoes.component.html',
  styleUrl: './barra-botoes.component.scss',
  standalone: true,
  imports: [
    CommonModule,
  ],
})
export class BarraBotoesComponent implements OnInit, OnDestroy {

  @Input() titulo: string = '';
  @Input() descricao: string = '';
  @Input() onButtonClick: () => void = () => { };

  private readonly subscriptions: Subscription = new Subscription();

  dispositivo: string = '';

  constructor(
    private readonly dispositivoService: DispositivoService,
    private readonly router: Router,
  ) { }

  ngOnInit(): void {
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  voltar() {
    this.router.navigate(['/']);
  }

  limpar() {
    this.onButtonClick();
  }

  verificarDispositivo(dispositivo: string) {
    this.dispositivo = dispositivo;
    switch (dispositivo) {
      case Dispositivos.XSMALL:
        break;
      case Dispositivos.SMALL:
        break;
      case Dispositivos.MEDIUM:
        break;
      case Dispositivos.LARGE:
        break;
      case Dispositivos.XLARGE:
        break;
      default:
        break;
    }
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
        this.verificarDispositivo(dispositivo);
      })
    );
  }

}
